import type { LatLng } from './geo';
import { sortByDistance, type Pharmacy, type PharmacyWithDistance } from './overpass';

/** Offline copy of OSM pharmacies, generated by `npm run snapshot`. */
export interface Snapshot {
  generatedAt: string;
  /** ISO 3166-1 alpha-2 codes of the covered countries. */
  countries: string[];
  pharmacies: Pharmacy[];
}

/** `name:<lang>` tags worth keeping in the snapshot — the UI languages. */
export const SNAPSHOT_LANGUAGES = ['en', 'fi', 'sv'];

/** Same reach as the largest live search radius. */
const MAX_DISTANCE_M = 50_000;

let cached: Promise<Snapshot> | null = null;

/** Fetched lazily, and only once, so the file never weighs on the initial page load. */
export function loadSnapshot(): Promise<Snapshot> {
  cached ??= fetch(`${import.meta.env.BASE_URL}data/pharmacies.json`).then((res) => {
    if (!res.ok) throw new Error(`Snapshot responded ${res.status}`);
    return res.json() as Promise<Snapshot>;
  });
  // Allow a retry after a failed load instead of caching the failure.
  cached.catch(() => (cached = null));
  return cached;
}

export function nearestInSnapshot(
  snapshot: Snapshot,
  origin: LatLng,
  limit = 20,
): PharmacyWithDistance[] {
  return sortByDistance(origin, snapshot.pharmacies)
    .filter((p) => p.distance <= MAX_DISTANCE_M)
    .slice(0, limit);
}
